    shop.catalog.handle_add_product({"sku": "ANT", "name": "Ant", "unit_price_cents": 1, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "ZED", "name": "Zed", "unit_price_cents": 1, "on_hand": 0})
